<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#1f2937;font-size:11px}.head{border-bottom:2px solid #1d4ed8;margin-bottom:20px}.row{display:flex;justify-content:space-between}.amount{text-align:right}table{width:100%;border-collapse:collapse}th,td{padding:7px;border-bottom:1px solid #e5e7eb}th{text-align:left;background:#f3f4f6}</style></head><body><div class="head"><h1>{{ $period->name }} Payslip</h1><p>{{ $item->employee->user->full_name }} · {{ $item->employee->employee_no }}</p></div><table><tr><th>Earnings</th><th class="amount">Amount</th></tr><tr><td>Basic pay</td><td class="amount">{{ number_format($snapshot['basic_pay'] ?? $item->basic_pay, 2) }}</td></tr><tr><td>Overtime and allowances</td><td class="amount">{{ number_format(($snapshot['overtime_pay'] ?? $item->overtime_pay)+($snapshot['allowances'] ?? $item->allowances), 2) }}</td></tr><tr><th>Gross pay</th><th class="amount">{{ number_format($snapshot['gross_pay'] ?? $item->gross_pay, 2) }}</th></tr><tr><th>Deductions</th><th class="amount">{{ number_format($snapshot['total_deductions'] ?? $item->total_deductions, 2) }}</th></tr><tr><th>Net pay</th><th class="amount">{{ number_format($snapshot['net_pay'] ?? $item->net_pay, 2) }}</th></tr></table><p>Archived payroll document. Generated {{ now()->format('Y-m-d H:i') }}.</p></body></html>
